// import(중복 정의 금지). 미번역 slug는 KO 라우트에서 EN 폴백 + KO_FALLBACK_NOTICE 배너로 처리.
// 진행: 13/13 완료 (settings-sheet · gf-warpage · gate-mark · metallic-flake · nmt-bond · nmt-resin ·
//        nmt-antenna · nmt-metal-resin · fiber-float · halogen-free · clamp-tonnage · weld-line · splay).
import type { Note, NoteBlock, NoteDiagramId } from './notes';

const p = (text: string): NoteBlock => ({ type: 'p', text });
const h2 = (text: string): NoteBlock => ({ type: 'h2', text });
const diagram = (id: NoteDiagramId): NoteBlock => ({ type: 'diagram', id });
const image = (src: string, alt: string, caption?: string): NoteBlock => ({ type: 'image', src, alt, caption });

export const KO_FALLBACK_NOTICE = '이 글의 한국어판은 준비 중입니다. 아래는 영문 원문입니다.';

